if($page==='assessment'){require_login();if(setting('assessment_enabled','1')!=='1')exit('Bài trắc nghiệm đang tạm đóng.');$questions=db()->query("SELECT * FROM questions WHERE status='active' ORDER BY sort_order,id")->fetchAll();if(!$questions)exit('Ngân hàng câu hỏi chưa sẵn sàng.');$pageTitle='Khám phá sở thích & thế mạnh';require __DIR__.'/app/header.php';?><div class="assessment-wrap"><div class="mb-4 flex items-center justify-between gap-4"><div><span class="badge badge-purple">✦ Khảo sát sở thích Holland (RIASEC)</span><h1 class="mt-2 text-2xl font-black">Khám phá bản thân</h1></div><div class="text-right"><b id="progressText">Câu 1 / <?=count($questions)?></b><small id="saveStatus" class="block text-slate-400">Tiến độ được lưu trên thiết bị</small></div></div><div class="progress-track"><div id="progressBar" class="progress-bar" style="width:<?=100/count($questions)?>%"></div></div><div class="my-4 flex flex-wrap justify-between gap-2 text-xs font-semibold text-slate-400"><span>Hãy chọn mức độ phản ánh đúng nhất với bạn trong thời gian gần đây</span><button id="resetDraft" type="button" class="text-brand-600 hover:underline">Làm lại từ đầu</button></div><form method="post" id="assessmentForm" data-submit-loading><?=csrf_field()?><input type="hidden" name="duration_seconds" id="riasecDurationSeconds" value="0"><?php foreach($questions as $i=>$q):$qMeta=riasec_question_meta($q['riasec_type'],(int)$q['sort_order']);?><section class="card question <?=$i===0?'active':''?>" data-index="<?=$i?>"><div class="flex items-center justify-between mb-2"><span class="badge badge-subtle"><?=e($qMeta['icon'].' '.$qMeta['label'])?></span><span class="text-sm font-bold text-slate-400"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span></div><h2 class="text-lg font-bold text-slate-900 mb-1"><?=e($q['content'])?></h2><p class="text-xs text-slate-500 mb-4"><?=e($qMeta['context'])?></p><div class="scale"><?php foreach([1=>'Hoàn toàn không',2=>'Ít đúng',3=>'Phân vân',4=>'Khá đúng',5=>'Rất đúng'] as $v=>$label):?><input type="radio" id="q<?=$q['id']?>-<?=$v?>" name="answers[<?=$q['id']?>]" value="<?=$v?>" data-question="<?=$q['id']?>"><label for="q<?=$q['id']?>-<?=$v?>"><b><?=$v?></b><span><?=$label?></span></label><?php endforeach;?></div><div class="question-actions mt-6 flex items-center justify-between"><button type="button" class="btn btn-outline prev" <?=$i===0?'disabled':''?>>← Câu trước</button><?php if($i<count($questions)-1):?><button type="button" class="btn btn-primary next">Câu tiếp theo →</button><?php else:?><button class="btn btn-primary btn-lg" type="submit">Hoàn thành & Xem kết quả →</button><?php endif;?></div></section><?php endforeach;?></form></div><div id="loadingOverlay" class="loading-overlay"><div class="loading-panel"><div class="spinner"></div><span class="badge badge-purple">✦ Đang phân tích</span><h2 class="my-4 text-2xl font-black">Đang tổng hợp hồ sơ của bạn</h2><p class="text-slate-500">Hệ thống đang đối chiếu 6 nhóm sở thích và chuẩn bị gợi ý nghề nghiệp phù hợp.</p></div></div><script>const startedAt=Date.now(),qs=[...document.querySelectorAll('.question')],bar=document.getElementById('progressBar'),txt=document.getElementById('progressText'),save=document.getElementById('saveStatus'),durInput=document.getElementById('riasecDurationSeconds'),draftKey='jobsimu_riasec_<?=user()['id']?>';let current=0;function show(n){qs[current].classList.remove('active');current=Math.max(0,Math.min(n,qs.length-1));qs[current].classList.add('active');bar.style.width=((current+1)/qs.length*100)+'%';txt.textContent=`Câu ${current+1} / ${qs.length}`;localStorage.setItem(draftKey+'_current',current);scrollTo({top:70,behavior:'smooth'})}function saveDraft(){const data={};document.querySelectorAll('input[type=radio]:checked').forEach(i=>data[i.dataset.question]=i.value);localStorage.setItem(draftKey,JSON.stringify(data));save.textContent='✓ Đã tự động lưu';setTimeout(()=>save.textContent='Tiến độ được lưu trên thiết bị',1600)}try{const data=JSON.parse(localStorage.getItem(draftKey)||'{}');Object.entries(data).forEach(([q,v])=>document.querySelector(`[data-question="${q}"][value="${v}"]`)?.click());const saved=Number(localStorage.getItem(draftKey+'_current')||0);if(saved>0&&saved<qs.length)show(saved)}catch(e){}document.querySelectorAll('input[type=radio]').forEach(i=>i.addEventListener('change',saveDraft));document.querySelectorAll('.next').forEach(b=>b.onclick=()=>{if(!qs[current].querySelector('input:checked')){showToast('Hãy chọn một mức độ phù hợp với bạn.');return}show(current+1)});document.querySelectorAll('.prev').forEach(b=>b.onclick=()=>show(current-1));document.getElementById('assessmentForm').addEventListener('submit',()=>{if(durInput)durInput.value=String(Math.max(1,Math.round((Date.now()-startedAt)/1000)));});document.getElementById('resetDraft').onclick=()=>{if(confirm('Xóa toàn bộ câu trả lời đã lưu và làm lại?')){localStorage.removeItem(draftKey);localStorage.removeItem(draftKey+'_current');document.querySelectorAll('input[type=radio]').forEach(i=>i.checked=false);show(0)}};</script><?php require __DIR__.'/app/footer.php';exit;}

if($page==='result'){require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM assessments WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);$r=$s->fetch();if(!$r)exit('Không tìm thấy kết quả.');$answers=json_decode($r['answers']??'[]',true)?:[];$scores=json_decode($r['scores'],true)?:[];$efficacyScores=json_decode($r['efficacy_scores']??'{}',true)?:[];$zScores=json_decode($r['ipsative_z_scores']??'{}',true)?:[];$validityMetrics=json_decode($r['validity_metrics']??'{}',true)?:[];$advice=json_decode($r['ai_advice']?:'{}',true);$s=db()->prepare('SELECT c.*,m.match_percent,m.rank_order FROM assessment_matches m JOIN careers c ON c.id=m.career_id WHERE m.assessment_id=? ORDER BY m.rank_order');$s->execute([$id]);$matches=$s->fetchAll();if(!$matches){recommendations_refresh_current((int)user()['id']);$s->execute([$id]);$matches=$s->fetchAll();}$userSims=[];$simS=db()->prepare('SELECT career_id,score,reflection_feeling,reflection_note,completed_at FROM simulation_attempts WHERE user_id=? ORDER BY completed_at DESC');$simS->execute([user()['id']]);foreach($simS->fetchAll() as $srow){if(!isset($userSims[$srow['career_id']]))$userSims[$srow['career_id']]=$srow;}$studentFeedback=$validityMetrics['student_feedback']??'';$feedbackUpdatedAt=$validityMetrics['feedback_updated_at']??'';$pageTitle='Hồ sơ sở thích Holland '.$r['result_code'];require __DIR__.'/app/header.php';?><section class="page-head"><div class="container"><nav class="breadcrumb mb-3" aria-label="Đường dẫn trang"><a href="<?=url('index.php?page=home')?>">Trang chủ</a><span class="breadcrumb-sep">/</span><a href="<?=url('index.php?page=assessment-hub')?>">Hiểu bản thân</a><span class="breadcrumb-sep">/</span><span aria-current="page">Hồ sơ sở thích Holland</span></nav><div class="flex flex-wrap items-center justify-between gap-4"><div><span class="badge badge-purple mb-2">Hồ sơ khám phá nghề</span><h1 class="page-title mb-1">Mã Holland của bạn: <span class="text-brand-600"><?=e($r['result_code'])?></span></h1><p class="page-subtitle">Ngày hoàn thành: <?=date('d/m/Y H:i',strtotime($r['completed_at']))?> · Tổng hợp từ câu trả lời tự khai theo chuẩn O*NET</p></div><div class="flex flex-wrap gap-2"><a class="btn btn-outline btn-sm" href="<?=url('index.php?page=assessment')?>">↻ Làm lại trắc nghiệm</a><a class="btn btn-primary btn-sm" href="<?=url('index.php?page=assessment-report')?>">Mở báo cáo tổng hợp →</a></div></div></div></section><div class="container py-8 space-y-8"><!-- 1. THÔNG TIN HỌC SINH ĐÃ CUNG CẤP --><section class="card p-6" aria-labelledby="sec-provided-info"><div class="flex flex-wrap items-center justify-between gap-3 mb-4 border-b border-slate-100 pb-3"><div><h2 id="sec-provided-info" class="text-base font-bold text-slate-900 flex items-center gap-2"><span>📋</span> 1. Thông tin bạn đã cung cấp</h2><p class="text-xs text-slate-500">Dữ liệu do bạn tự báo cáo tại thời điểm khảo sát, phản ánh sở thích và cảm nhận chủ quan.</p></div><span class="badge badge-subtle text-xs">Nguồn: Tự khai (Self-Reported)</span></div><div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3 text-xs"><div class="p-3 bg-slate-50 rounded-xl border border-slate-100"><span class="text-slate-400 block font-semibold mb-1">Thời điểm hoàn thành</span><strong class="text-slate-800 text-sm"><?=date('d/m/Y H:i',strtotime($r['completed_at']))?></strong></div><div class="p-3 bg-slate-50 rounded-xl border border-slate-100"><span class="text-slate-400 block font-semibold mb-1">Số câu hỏi đã trả lời</span><strong class="text-slate-800 text-sm"><?=count($answers)>0?count($answers).' câu RIASEC':'30 câu RIASEC'?></strong></div><div class="p-3 bg-slate-50 rounded-xl border border-slate-100"><span class="text-slate-400 block font-semibold mb-1">Độ phân hóa sở thích</span><strong class="text-slate-800 text-sm"><?=isset($validityMetrics['differentiation_index'])?(int)$validityMetrics['differentiation_index'].'/100':'Tiêu chuẩn'?></strong><small class="text-slate-400 block"><?=!empty($validityMetrics['validity_flag'])&&$validityMetrics['validity_flag']==='flat'?'Điểm số tương đối đồng đều':'Độ nét sở thích rõ ràng'?></small></div><div class="p-3 bg-slate-50 rounded-xl border border-slate-100"><span class="text-slate-400 block font-semibold mb-1">Thời gian phản hồi</span><strong class="text-slate-800 text-sm"><?=!empty($validityMetrics['duration_seconds'])?round($validityMetrics['duration_seconds']/60,1).' phút':'Khoảng 3-5 phút'?></strong></div></div><?php if(!empty($validityMetrics['warning_message'])):?><div class="mt-3 p-3 bg-amber-50 border border-amber-200 rounded-xl text-xs text-amber-800"><strong>⚠️ Lưu ý về độ phân hóa:</strong> <?=e($validityMetrics['warning_message'])?></div><?php endif;?></section><!-- 2. KẾT QUẢ SỞ THÍCH VÀ THIÊN HƯỚNG --><section class="card p-6" aria-labelledby="sec-scores"><div class="flex items-center justify-between mb-4 border-b border-slate-100 pb-3"><div><h2 id="sec-scores" class="text-base font-bold text-slate-900 flex items-center gap-2"><span>🧭</span> 2. Kết quả sở thích & Thiên hướng RIASEC</h2><p class="text-xs text-slate-500">Đối chiếu 6 nhóm sở thích. Điểm Z-score nội tại phản ánh mức độ bạn ưu tiên từng nhóm so với chính mình.</p></div><span class="badge badge-purple text-xs font-bold">Mã Holland: <?=e($r['result_code'])?></span></div><div class="score-grid"><?php foreach($scores as $type=>$score):$zVal=isset($zScores[$type])?(float)$zScores[$type]:null;$effVal=isset($efficacyScores[$type])?(int)$efficacyScores[$type]:null;?><div class="score-item"><div class="score-ring" style="--v:<?=$score?>;--c:<?=riasec_colors()[$type]?>"><span><?=$score?>%</span></div><b class="text-sm"><?=e(riasec_labels()[$type])?> (<?=$type?>)</b><?php if($zVal!==null):?><small class="muted block">Z nội tại: <?=($zVal>=0?'+':'').number_format($zVal,2)?></small><?php endif;?><small class="muted block"><?php if($effVal!==null):?>Tự tin: <?=$effVal?>%<?php else:?>Sở thích: <?=$score?>%<?php endif;?></small></div><?php endforeach;?></div><?php if(empty($efficacyScores)):?><div class="mt-4 p-3 bg-slate-50 border border-slate-100 rounded-xl text-xs text-slate-600 flex items-center justify-between gap-3"><span>💡 Bài làm này thuộc phiên bản tiêu chuẩn RIASEC O*NET. Để xem thêm độ tự tin thực hiện công việc (Self-Efficacy), bạn có thể bổ sung khảo sát tại Trung tâm đánh giá.</span><a href="<?=url('index.php?page=assessment-hub')?>" class="btn btn-outline btn-sm shrink-0">Bổ sung Tự hiệu quả →</a></div><?php endif;?><?php if(!empty($advice['summary'])):?><div class="mt-4 p-4 bg-purple-50/60 rounded-xl border border-purple-100 text-slate-800 text-sm leading-relaxed"><strong>✨ Phân tích định hướng:</strong> <?=e($advice['summary'])?></div><?php endif;?></section><!-- 3. GIỚI HẠN DIỄN GIẢI & LƯU Ý PHƯƠNG PHÁP --><section class="notice-box" aria-labelledby="sec-limits"><h2 id="sec-limits" class="text-sm font-bold text-slate-900 mb-2 flex items-center gap-2"><span>ℹ️</span> 3. Giới hạn diễn giải & Lưu ý phương pháp</h2><div class="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs text-slate-600 leading-relaxed"><div class="p-3 bg-white/70 rounded-lg border border-slate-200"><strong class="text-slate-800 block mb-1">📸 Ảnh chụp tại thời điểm hiện tại:</strong>Kết quả này phản ánh cảm nhận và sở thích tự khai của bạn lúc làm bài. Sở thích nghề nghiệp sẽ tiếp tục biến chuyển theo trải nghiệm học tập, rèn luyện và tiếp xúc thực tế.</div><div class="p-3 bg-white/70 rounded-lg border border-slate-200"><strong class="text-slate-800 block mb-1">🌱 Không gán nhãn cố định con người:</strong>Hệ thống không đánh giá năng lực toàn diện, phẩm chất đạo đức hay trí tuệ của bạn. Không có ngành nghề nào bạn bị "loại trừ" chỉ vì một kết quả khảo sát.</div><div class="p-3 bg-white/70 rounded-lg border border-slate-200"><strong class="text-slate-800 block mb-1">🎯 Không phải tỷ lệ thành công đảm bảo:</strong>Tỷ lệ % trùng khớp chỉ đo lường mức độ tương đồng giữa câu trả lời của bạn với hồ sơ vị trí nghề nghiệp O*NET; không phải dự báo xác suất thành công hay thu nhập.</div><div class="p-3 bg-white/70 rounded-lg border border-slate-200"><strong class="text-slate-800 block mb-1">🔍 Điểm khởi đầu để phản tư:</strong>Hãy dùng danh sách gợi ý làm chất liệu để trò chuyện cùng gia đình, thầy cô và tham gia trải nghiệm thực tế tại phòng mô phỏng nghề nghiệp.</div></div></section><!-- 4. NGHỀ TƯƠNG ĐỒNG VÀ ĐỐI CHIẾU THỰC TẾ MÔ PHỎNG --><section class="card p-6" aria-labelledby="sec-next"><div class="flex items-center justify-between mb-4 border-b border-slate-100 pb-3"><div><h2 id="sec-next" class="text-base font-bold text-slate-900 flex items-center gap-2"><span>🚀</span> 4. Nghề tương đồng & Đối chiếu thực tế phòng mô phỏng</h2><p class="text-xs text-slate-500">Các vị trí nghề có hồ sơ sở thích trùng khớp nhất với mã <?=e($r['result_code'])?> của bạn, kèm đối chiếu với kết quả trải nghiệm thực tế.</p></div><span class="text-xs text-slate-400">Hiển thị top <?=min(8,count($matches))?> nghề</span></div><div class="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6"><?php foreach(array_slice($matches,0,8) as $job):$matrix=career_matrix_status((int)$job['match_percent'],$userSims[$job['id']]??null);$hasSim2d=simulation_for_career($job)!==null;$isSim3d=($job['id']==5||$job['slug']==='giao-vien');$simAttempt=$userSims[$job['id']]??null;?><div class="card p-4 flex flex-col justify-between gap-3 hover:border-brand-300 transition-all"><div><div class="flex items-start justify-between gap-3 mb-2"><div class="flex items-start gap-3"><span class="text-3xl p-2 bg-slate-50 rounded-xl border border-slate-100"><?=e($job['icon']?:'💼')?></span><div><h3 class="font-bold text-base text-slate-900"><a href="<?=url('index.php?page=career&id='.$job['id'])?>" class="hover:text-brand-600"><?=e($job['title'])?></a></h3><span class="badge badge-subtle text-[11px]"><?=e($matrix['badge'])?></span></div></div><span class="badge badge-purple text-xs font-bold"><?=(int)$job['match_percent']?>%</span></div><p class="text-xs text-slate-600 line-clamp-2 mb-3"><?=e($job['short_description'])?></p><div class="p-2.5 bg-slate-50 rounded-lg border border-slate-100 text-[11px] space-y-1 mb-2"><div><span class="text-slate-400">Khảo sát lý thuyết:</span> <strong class="text-slate-700">Tương đồng <?=(int)$job['match_percent']?>% theo O*NET</strong></div><div><span class="text-slate-400">Trải nghiệm thực tế:</span> <?php if($simAttempt):?><span class="text-emerald-700 font-semibold">✓ Đã thử (Điểm tình huống: <?=(int)$simAttempt['score']?>) · <?=$simAttempt['reflection_feeling']==='excited'?'Hào hứng':($simAttempt['reflection_feeling']==='challenged'?'Thử thách':'Cần cân nhắc')?></span><?php if(!empty($simAttempt['reflection_note'])):?><p class="text-slate-500 italic mt-0.5">"<?=e($simAttempt['reflection_note'])?>"</p><?php endif;?><?php else:?><span class="text-slate-500">Chưa thử mô phỏng</span><?php endif;?></div></div></div><div class="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-slate-100 text-xs"><?php if($isSim3d):?><a href="<?=url('index.php?page=simulation-3d')?>" class="btn btn-outline btn-sm text-brand-600">🎮 Vào mô phỏng 3D →</a><?php elseif($hasSim2d):?><a href="<?=url('index.php?page=simulation&id='.$job['id'])?>" class="btn btn-outline btn-sm text-brand-600"><?=$simAttempt?'↻ Thử lại phòng 2D':'Vào phòng thử 2D →'?></a><?php else:?><span class="text-[11px] text-slate-400">Đang xây dựng tình huống</span><?php endif;?><a href="<?=url('index.php?page=career&id='.$job['id'])?>" class="font-bold text-brand-600 hover:underline">Chi tiết & Tuyển sinh →</a></div></div><?php endforeach;?></div></section><!-- 5. PHẢN HỒI & BỔ SUNG TỪ HỌC SINH --><section class="card p-6" aria-labelledby="sec-student-reflection"><div class="flex items-center justify-between mb-4 border-b border-slate-100 pb-3"><div><h2 id="sec-student-reflection" class="text-base font-bold text-slate-900 flex items-center gap-2"><span>✍️</span> 5. Ghi chú phản tư của bạn ("Kết quả này chưa giống em ở điểm n